import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import api from '../../services/api'
export default function AddProduct(){const nav=useNavigate();const [form,setForm]=useState({name:'',description:'',price:'',category:'',stock_quantity:0,is_available:true});function update(e){setForm({...form,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value})}async function save(e){e.preventDefault();await api.post('/api/vendor/products',{...form,price:Number(form.price),stock_quantity:Number(form.stock_quantity)});nav('/vendor/products')}return <div className="form-page"><span className="section-kicker">Catalog management</span><h1 className="vendor-title">Add Product</h1><form className="vendor-form" onSubmit={save}>{['name','description','category','price','stock_quantity'].map(name=><label key={name}>{name.replace('_',' ')}{name==='description'?<textarea name={name} value={form[name]} onChange={update} required/>:<input name={name} type={['price','stock_quantity'].includes(name)?'number':'text'} value={form[name]} onChange={update} required/>}</label>)}<label className="toggle"><input type="checkbox" name="is_available" checked={form.is_available} onChange={update}/> Available</label><button className="auth-submit">Save Product</button></form></div>}
